import {createHash} from 'node:crypto';
export const sha256=bytes=>createHash('sha256').update(bytes).digest('hex');
export function workerBundle(common){
 const revision='phase9-6-common-1',digest=sha256(common),tag=digest.slice(0,16);
 if(!common.toString('utf8').includes(`self.ed4CommonWorkerRevision = '${revision}'`))throw Error('Missing common Worker compatibility marker');
 const file=`dos-worker-common-phase9-6-${tag}.js`;
 const code=`// Generated from the reviewed common Worker. GPL-2.0-only.
self.ed4DiagnosticEngine='phase9-6';
const bootstrapSend=self.postMessage.bind(self);
let bootstrapStage='import-common-worker';
try {
  importScripts('./${file}');
  bootstrapStage='check-common-worker';
  if(self.ed4CommonWorkerRevision!=='${revision}')throw Error('Common Worker compatibility marker mismatch');
  bootstrapSend({name:'ed4-worker-bootstrap',props:{revision:'${revision}',common:'${file}',sha256:'${digest}'}});
} catch (error) {
  const cause=typeof error?.message==='string'?error.message.slice(0,640):'Unknown importScripts failure';
  bootstrapSend({name:'ed4-runtime-error',props:{source:'worker-bootstrap',name:'Error',stage:bootstrapStage,filename:'${file}',message:'Phase 9-6 Worker 로딩/호환성 오류 (${file}): '+cause+'. 온라인에서 모든 실행기 탭/PWA를 닫고 업데이트 후 다시 여세요. 사이트 데이터는 삭제하지 마세요. 안정 엔진으로 자동 대체하지 않았습니다.'}});
  self.close();
}
`;
 const entrySha256=sha256(code),entry=`dos-worker-phase9-6-${entrySha256.slice(0,16)}.js`;
 const manifest={revision,entry,common:file,sha256:digest,entrySha256};
 return {manifest,code,typescript:`// Generated by scripts/prepare-phase9-6-worker.mjs; do not edit.\nexport const PHASE96_WORKER=${JSON.stringify(manifest,null,2)} as const;\n`};
}
export function checkWorkerBundle(common,entry,pinned,manifest){
 const expected=workerBundle(common);
 if(!Buffer.from(common).equals(Buffer.from(pinned))||sha256(pinned)!==expected.manifest.sha256)throw Error('Phase 9-6 common Worker bytes/hash mismatch');
 if(sha256(entry)!==expected.manifest.entrySha256||!Buffer.from(entry).equals(Buffer.from(expected.code)))throw Error('Phase 9-6 entry Worker bytes/hash mismatch');
 if(JSON.stringify(manifest)!==JSON.stringify(expected.manifest))throw Error('Phase 9-6 Worker manifest mismatch');
 return expected;
}
